//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_apDisposition(value: *mut FlightStack::QualifiedApDisposition) -> bool;
  fn get_qualifiedAttitude(value: *mut FlightStack::QualifiedAttitude) -> bool;
  fn get_apGuidance(value: *mut FlightStack::ApGuidanceAndValidity) -> bool;
  fn put_pairedApStatus(value: *mut FlightStack::PairedApStatus) -> bool;
  fn put_apGuidanceRequest(value: *mut FlightStack::ApGuidanceRequestValue) -> bool;
  fn put_apActiveClearInhibit(value: *mut bool) -> bool;
  fn put_actuationAuthority(value: *mut bool) -> bool;
}

pub fn unsafe_get_apDisposition() -> FlightStack::QualifiedApDisposition
{
  unsafe {
    let value: *mut FlightStack::QualifiedApDisposition = &mut FlightStack::QualifiedApDisposition::default();
    get_apDisposition(value);
    return *value;
  }
}

pub fn unsafe_get_qualifiedAttitude() -> FlightStack::QualifiedAttitude
{
  unsafe {
    let value: *mut FlightStack::QualifiedAttitude = &mut FlightStack::QualifiedAttitude::default();
    get_qualifiedAttitude(value);
    return *value;
  }
}

pub fn unsafe_get_apGuidance() -> FlightStack::ApGuidanceAndValidity
{
  unsafe {
    let value: *mut FlightStack::ApGuidanceAndValidity = &mut FlightStack::ApGuidanceAndValidity::default();
    get_apGuidance(value);
    return *value;
  }
}

pub fn unsafe_put_pairedApStatus(value: &FlightStack::PairedApStatus) -> bool
{
  unsafe {
    return put_pairedApStatus(value as *const FlightStack::PairedApStatus as *mut FlightStack::PairedApStatus);
  }
}

pub fn unsafe_put_apGuidanceRequest(value: &FlightStack::ApGuidanceRequestValue) -> bool
{
  unsafe {
    return put_apGuidanceRequest(value as *const FlightStack::ApGuidanceRequestValue as *mut FlightStack::ApGuidanceRequestValue);
  }
}

pub fn unsafe_put_apActiveClearInhibit(value: &bool) -> bool
{
  unsafe {
    return put_apActiveClearInhibit(value as *const bool as *mut bool);
  }
}

pub fn unsafe_put_actuationAuthority(value: &bool) -> bool
{
  unsafe {
    return put_actuationAuthority(value as *const bool as *mut bool);
  }
}

