#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_apDisposition: Mutex<Option<FlightStack::QualifiedApDisposition>> = Mutex::new(None);
  pub static ref IN_qualifiedAttitude: Mutex<Option<FlightStack::QualifiedAttitude>> = Mutex::new(None);
  pub static ref IN_apGuidance: Mutex<Option<FlightStack::ApGuidanceAndValidity>> = Mutex::new(None);
  pub static ref OUT_pairedApStatus: Mutex<Option<FlightStack::PairedApStatus>> = Mutex::new(None);
  pub static ref OUT_apGuidanceRequest: Mutex<Option<FlightStack::ApGuidanceRequestValue>> = Mutex::new(None);
  pub static ref OUT_apActiveClearInhibit: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref OUT_actuationAuthority: Mutex<Option<bool>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_apDisposition.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_qualifiedAttitude.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_apGuidance.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_pairedApStatus.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_apGuidanceRequest.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_apActiveClearInhibit.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_actuationAuthority.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_apDisposition(value: *mut FlightStack::QualifiedApDisposition) -> bool
{
  unsafe {
    let guard = IN_apDisposition.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

